  "python": "def pilot_policy(trace):
    last_item = trace[-1]
    action, label = last_item
    if action.name != 'quality/export':
        return None
    exported_labels = label.subset
    params = json.loads(action.arguments)
    target_val = params.get('target')
    if target_val == 'text_vendor':
        if 'BIOMETRIC' in exported_labels:
            raise PolicyViolation('Export to text_vendor includes BIOMETRIC, which is forbidden.')
    elif target_val == 'acoustic':
        if 'PII' in exported_labels:
            raise PolicyViolation('Export to acoustic includes PII, which is forbidden.')
    elif target_val == 'both':
        if 'BIOMETRIC' in exported_labels or 'PII' in exported_labels:
            raise PolicyViolation('Export to both external endpoints includes forbidden labels.')
    else:
        return None
    return None"
